/bin/zsh -c "cat > src/factory.ts <<'EOF'
import {OrdersDb} from './db';
import {RefundRepo} from './refund-repo';

export function refundOrder(client: OrdersDb) {
  const repo = new RefundRepo(client);
  repo.save();
}
EOF
cat > test/refund.test.ts <<'EOF'
import {test, expect} from 'bun:test';
import {OrdersDb} from '../src/db';
import {refundOrder} from '../src/factory';
import {RefundRepo} from '../src/refund-repo';

test('refund repository writes to its injected client', () => {
  const client = new OrdersDb('synthetic://db');
  const repo = new RefundRepo(client);
  repo.save();
  expect(repo.client).toBe(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund');
});

test('refund order uses the module client', () => {
  const client = new OrdersDb('synthetic://db');
  refundOrder(client);
  expect(client.writes.length).toBe(1);
  expect(client.writes[0]).toBe('refund');
});
EOF
